#!/usr/bin/env python3
"""Compute ground truth for CSX-189_Q1 from local package evidence."""

from __future__ import annotations

import html
import json
import math
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-189_Q1"
PACKAGE_ID = "CSX-189"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_anchor_report_USGS_remote_sensing_image.html",
    "data/event_reports/event_reports_004_Locked_event_anchor_2022_Uljin_wildfire_near_Hanul_nuclear_plant_corridor.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/remote_sensing/remote_sensing_002_Google_Satellite_Embedding_annual_cosine-change_stats.json",
]


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"script", "style", "noscript"}:
            self.skip_depth += 1
        if tag in {"h1", "h2", "p", "li"}:
            self.parts.append("\n")

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if self.skip_depth:
            return
        text = " ".join(data.split())
        if text:
            self.parts.append(text + " ")

    def text(self) -> str:
        return " ".join("".join(self.parts).split())


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def load_json(package_dir: Path, rel_path: str) -> Any:
    return json.loads((package_dir / rel_path).read_text(encoding="utf-8"))


def report_text(package_dir: Path) -> str:
    parser = TextExtractor()
    parser.feed((package_dir / SOURCE_FILES[1]).read_text(encoding="utf-8", errors="replace"))
    return html.unescape(parser.text())


def extract_hectares(text: str) -> int:
    match = re.search(r"nearly\s+([0-9,]+)\s+hectares", text, re.I)
    if not match:
        raise ValueError("charred-area phrase was not found in the local report")
    return int(match.group(1).replace(",", ""))


def burn_change_metrics(dnbr: dict[str, Any]) -> dict[str, float]:
    stats = dnbr["stats"]
    mean_value = float(stats["sentinel2_dnbr_mean"])
    max_value = float(stats["sentinel2_dnbr_max"])
    return {
        "dnbr_mean": round(mean_value, 6),
        "dnbr_max": round(max_value, 6),
        "dnbr_max_to_mean_ratio": round(max_value / mean_value, 3),
    }


def main() -> None:
    pkg = package_root()
    event = load_json(pkg, SOURCE_FILES[0])
    locked = load_json(pkg, SOURCE_FILES[2])
    era5 = load_json(pkg, SOURCE_FILES[3])
    gpm = load_json(pkg, SOURCE_FILES[4])
    chirps = load_json(pkg, SOURCE_FILES[5])
    dnbr = load_json(pkg, SOURCE_FILES[6])
    annual_change = load_json(pkg, SOURCE_FILES[7])
    text = report_text(pkg)
    lower = text.lower()

    hectares = extract_hectares(text)
    burn = burn_change_metrics(dnbr)
    annual_mean = float(annual_change["stats"]["alphaearth_1_minus_cosine_mean"])
    era_stats = era5["stats"]
    wind_u = float(era_stats["u_component_of_wind_10m_mean"])
    wind_v = float(era_stats["v_component_of_wind_10m_mean"])
    wind_speed = math.hypot(wind_u, wind_v)
    wind_bearing = (math.degrees(math.atan2(wind_u, wind_v)) + 360.0) % 360.0
    precip_means = {
        "era5_land": float(era_stats["precipitation_sum_mm_mean"]),
        "gpm": float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps": float(chirps["stats"]["chirps_event_precip_mm_mean"]),
    }
    precip_values = list(precip_means.values())

    report_dry_wind_flag = int("strong winds" in lower and "dry weather" in lower)
    smoke_transport_flag = int("southern japan" in lower and "smoke" in lower)
    no_nuclear_damage_flag = int(
        not re.search(r"(radiation|reactor|nuclear).{0,80}(damage|release|leak|meltdown)", lower)
    )

    answer_metrics = {
        "report_dry_wind_flag": report_dry_wind_flag,
        "smoke_transport_flag": smoke_transport_flag,
        "era5_mean_wind_speed_mps": round(wind_speed, 3),
        "era5_wind_bearing_to_deg": round(wind_bearing, 1),
        "precip_mean_spread_mm": round(max(precip_values) - min(precip_values), 3),
        "dnbr_mean": burn["dnbr_mean"],
        "dnbr_max_to_mean_ratio": burn["dnbr_max_to_mean_ratio"],
        "dnbr_to_annual_change_mean_ratio": round(burn["dnbr_mean"] / annual_mean, 3),
        "reported_charred_area_km2": round(hectares * 0.01, 1),
    }
    tests = {
        "report_dry_wind_mechanism_test": "pass" if report_dry_wind_flag else "fail",
        "smoke_transport_context_test": "pass" if smoke_transport_flag else "fail",
        "positive_heterogeneous_burn_test": (
            "pass" if burn["dnbr_mean"] > 0 and burn["dnbr_max_to_mean_ratio"] >= 2.0 else "fail"
        ),
        "late_rain_control_test": "fail",
        "nuclear_damage_overclaim_test": "pass" if no_nuclear_damage_flag else "fail",
    }
    interpretation = (
        "The local package supports a dry, wind-assisted wildfire mechanism through the report text, "
        "a positive heterogeneous dNBR signal, and a 170.0 km2 reported burned-area anchor. "
        "Gridded precipitation remains context rather than a late-rain control, and the ledger should not infer "
        "nuclear-plant damage or radiation release."
    )

    primary_gt = {
        "answer": answer_metrics,
        "tests": tests,
        "interpretation": interpretation,
    }

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "uljin_report_burn_change_consistency_ledger",
        "primary_gt": primary_gt,
        "numeric_tolerances": {
            "era5_mean_wind_speed_mps": {"target": answer_metrics["era5_mean_wind_speed_mps"], "absolute_tolerance": 0.001},
            "era5_wind_bearing_to_deg": {"target": answer_metrics["era5_wind_bearing_to_deg"], "absolute_tolerance": 0.1},
            "precip_mean_spread_mm": {"target": answer_metrics["precip_mean_spread_mm"], "absolute_tolerance": 0.001},
            "dnbr_mean": {"target": answer_metrics["dnbr_mean"], "absolute_tolerance": 0.001},
            "dnbr_max_to_mean_ratio": {"target": answer_metrics["dnbr_max_to_mean_ratio"], "absolute_tolerance": 0.01},
            "dnbr_to_annual_change_mean_ratio": {"target": answer_metrics["dnbr_to_annual_change_mean_ratio"], "absolute_tolerance": 0.01},
            "reported_charred_area_km2": {"target": 170.0, "absolute_tolerance": 1.0},
        },
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": (
                f"{locked['temporal_window']['start_date']} to {locked['temporal_window']['end_date']}"
            ),
        },
        "key_values": {
            "report_flags": {
                "strong_winds_and_dry_weather": bool(report_dry_wind_flag),
                "smoke_toward_southern_japan": bool(smoke_transport_flag),
                "no_nuclear_damage_phrase": bool(no_nuclear_damage_flag),
            },
            "precipitation_means_mm": {key: round(value, 3) for key, value in precip_means.items()},
            "era5_wind_components_mps": {"u": round(wind_u, 3), "v": round(wind_v, 3)},
            "burn_change": burn,
            "annual_surface_change_mean": round(annual_mean, 6),
            "reported_charred_area_hectares": hectares,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Requested JSON ledger",
                    "points": 4,
                    "description": "Returns answer, tests, and interpretation with all requested numeric and pass/fail fields.",
                    "partial_credit": "Award 2-3 points for a mostly complete ledger with one missing metric family.",
                },
                {
                    "name": "Report mechanism extraction",
                    "points": 4,
                    "description": "Correctly identifies strong winds plus dry weather, smoke transport toward southern Japan, and absence of nuclear-damage evidence.",
                    "partial_credit": "Award roughly one point per correct report flag, with an extra point for avoiding overclaim.",
                },
                {
                    "name": "Gridded context calculations",
                    "points": 4,
                    "description": "Computes ERA5 mean wind speed and bearing, and the spread across ERA5, GPM, and CHIRPS precipitation means.",
                    "partial_credit": "Award partial credit across wind speed, bearing, and precipitation spread.",
                },
                {
                    "name": "Burn and area calculations",
                    "points": 4,
                    "description": "Correctly reports dNBR mean, dNBR max-to-mean ratio, dNBR-to-annual-change ratio, and converts nearly 17,000 hectares to 170.0 km2.",
                    "partial_credit": "Award 1 point for each correct burn or area anchor.",
                },
                {
                    "name": "Threshold states and rejected alternatives",
                    "points": 2,
                    "description": "Marks dry/wind mechanism, smoke transport, and heterogeneous burn as pass, late-rain control as fail, and nuclear-damage overclaim as pass/avoided.",
                    "partial_credit": "Award 1 point for the correct majority of test states.",
                },
                {
                    "name": "Concise interpretation and limits",
                    "points": 2,
                    "description": "Gives a ledger-bound interpretation and avoids plant damage, radiation, or exposure-to-loss statements.",
                    "partial_credit": "Award 1 point for a correct but wordy interpretation or one minor extra inference.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Point-weather products are intentionally not used; calculations rely on report text, package gridded summaries, dNBR, and annual embedding context.",
        },
    }

    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    output_path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
